    "hintAr": "العجلة النسبية للكرة بالنسبة لأرضية المصعد هي $a_{\\text{rel}} = g + a_e = 9.8 + 2.2 = 12\\text{ م/ث}^2$. استخدم $h = \\frac{1}{2} a_{\\text{rel}} t^2$.",
