    "questionEn": "The ratio of the apparent weight of a person in an ascending elevator with acceleration $a$ to his apparent weight when descending with the same acceleration $a$ is $\\frac{3}{1}$. Find the acceleration $a$ in $\\text{m/s}^2$ (take $g = 9.8\\text{ m/s}^2$).",
    "questionAr": "النسبة بين الوزن الظاهري لشخص داخل مصعد صاعد بعجلة $a$ إلى وزنه الظاهري عند هبوط المصعد بنفس العجلة $a$ هي $\\frac{3}{1}$. أوجد مقدار العجلة $a$ بـ $\\text{م/ث}^2$ (اعتبر $g = 9.8\\text{ م/ث}^2$).",
